//! Translation of the IR to C: one source file for the program that includes `neon.h`.
//!
//! The runtime (allocator, collector, strings, arrays, maps, formatting, the standard modules and the
//! checked arithmetic) is not generated: it is the hand-written pair `runtime/neon.h` +
//! `runtime/neon.c`. The generated file is the program only: its types and globals, string
//! constants, functions, and `main`.

mod emit;
mod names;

use std::fmt::Write as _;

use crate::ir::IrProgram;
use emit::{c_string, Gen};

/// The runtime's header and source, as shipped in `runtime/` (`neon runtime <dir>` writes them out).
pub const NEON_H: &str = include_str!("../../runtime/neon.h");
pub const NEON_C: &str = include_str!("../../runtime/neon.c");

/// Translates `prog` to C. Fails only for programs outside what the backend supports (a struct with
/// more than 64 fields).
pub fn emit_c(prog: &IrProgram) -> Result<String, String> {
    let out = Gen::new(prog).generate()?;
    let mut s = String::new();
    s.push_str("/* Generated by the Neon compiler.\n");
    s.push_str(" * Build: cc -O2 -I runtime program.c runtime/neon.c -o program -lm\n");
    s.push_str(" *   -DNDEBUG: release (no arithmetic traps or recursion guard); -DNEON_MAX_DEPTH=n; -DNEON_GC_STRESS");
    if prog.c_sources.is_empty() {
        s.push_str(" */\n");
    } else {
        s.push_str("\n *   the C modules: add -I <directory of the Neon program> */\n");
    }
    s.push_str("#include \"neon.h\"\n");

    // ---- C modules: part of this translation unit, so the compiler checks every call ---------
    if !prog.c_sources.is_empty() {
        section(&mut s, "C modules");
        for path in &prog.c_sources {
            if path.contains(['"', '\n']) {
                return Err(format!("the C file name `{path}` cannot be used in an #include"));
            }
            let _ = writeln!(s, "#include \"{}\"", path.replace('\\', "/"));
        }
    }

    // ---- declarations -------------------------------------------------------------------------
    section(&mut s, "Declarations");
    for t in &out.typedefs {
        let _ = writeln!(s, "{t}");
    }
    for e in &out.enums {
        let _ = writeln!(s, "{e}");
    }
    for g in &out.globals {
        let _ = writeln!(s, "{g}");
    }
    if !out.strs.is_empty() {
        let _ = writeln!(s, "static const struct {{ const char *s; size_t n; }} k_lit[{}] = {{", out.strs.len());
        for &i in &out.strs {
            let text = &prog.strings[i as usize];
            let _ = writeln!(s, "    {{{}, {}}},", c_string(text), text.len());
        }
        s.push_str("};\n");
        let _ = writeln!(s, "static Obj *k_str[{}];   /* string constants, created on first use */", out.strs.len());
        s.push_str("static Obj *kstr(int i);\n");
    }
    for p in &out.fn_protos {
        let _ = writeln!(s, "{p}");
    }

    // ---- program -----------------------------------------------------------------------------------
    section(&mut s, "Program");
    if !out.strs.is_empty() {
        s.push_str("static Obj *kstr(int i) {\n    if (UNLIKELY(k_str[i] == NULL)) k_str[i] = str_new(k_lit[i].s, k_lit[i].n);\n    return k_str[i];\n}\n\n");
    }
    s.push_str(
        "/* The collector's roots besides the frames: globals and string constants. */\nvoid user_roots(void) {\n",
    );
    for g in &out.ref_globals {
        let _ = writeln!(s, "    gc_mark({g});");
    }
    if !out.strs.is_empty() {
        let _ = writeln!(
            s,
            "    {{\n        int i;\n        for (i = 0; i < {}; i++) gc_mark(k_str[i]);\n    }}",
            out.strs.len()
        );
    }
    s.push_str("}\n\n");
    for b in &out.fn_bodies {
        s.push_str(b);
        s.push_str("\n\n");
    }
    s.pop();

    // ---- main ------------------------------------------------------------------------------------------
    section(&mut s, "Entry point");
    let _ = writeln!(
        s,
        "int main(int argc, char **argv) {{\n    rt_argc = argc;\n    rt_argv = argv;\n    {}();\n    fflush(stdout);\n    return 0;\n}}",
        out.entry
    );
    Ok(s)
}

fn section(s: &mut String, title: &str) {
    let _ = write!(s, "\n/* ---- {title} {}*/\n\n", "-".repeat(70usize.saturating_sub(title.len())));
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::driver::{compile_source, Options};
    use crate::vfs::MemVfs;

    fn c_of(src: &str) -> String {
        let c = compile_source("t.neon", src, &MemVfs::new(), &Options::default());
        assert!(!c.diags.has_errors(), "{}", c.render_diagnostics());
        emit_c(c.ir.as_ref().unwrap()).unwrap()
    }

    /// Every runtime function the generator names must exist in `neon.h` / `neon.c`.
    #[test]
    fn the_runtime_declares_what_the_generator_calls() {
        let c =
            c_of("fn main() { let a = input().parse_i64(); var v = [a, 2]; v.sort(); println(v); println(a * v[0]); }");
        for name in ["input", "rt_input", "parse_i64", "arr_sort", "mul_i64", "out_str", "gc_mark"] {
            let hit = NEON_H.contains(&format!(" {name}(")) || NEON_C.contains(&format!(" {name}("));
            assert!(c.contains(name) || hit, "{name}");
        }
        assert!(NEON_H.contains("static inline i64 mul_i64(i64 a, i64 b)"));
        assert!(NEON_H.contains("void user_roots(void);") && NEON_C.contains("int rt_argc;"));
    }

    #[test]
    fn the_header_is_self_contained_and_guarded() {
        assert!(NEON_H.starts_with("/*") && NEON_H.contains("#ifndef NEON_H\n#define NEON_H"));
        assert!(NEON_H.trim_end().ends_with("#endif"));
        // platform headers belong to neon.c; the header only needs the C library
        for h in ["windows.h", "unistd.h", "termios.h"] {
            assert!(!NEON_H.contains(h) && NEON_C.contains(h), "{h}");
        }
        // a function is either defined once in neon.c, or `static inline` in the header
        assert!(NEON_C.contains("#include \"neon.h\""));
    }

    #[test]
    fn c_strings_are_escaped() {
        assert_eq!(c_string("a\"b\\c\n?"), "\"a\\\"b\\\\c\\n\\?\"");
        assert_eq!(c_string("é"), "\"\\303\\251\"");
    }

    #[test]
    fn the_program_file_holds_the_program_only() {
        let tiny = c_of("println(1 + 2);");
        assert!(tiny.contains("#include \"neon.h\"") && tiny.contains("sb_i64") && tiny.contains("int main("));
        assert!(!tiny.contains("gc_collect(void) {") && !tiny.contains("map_put(") && tiny.lines().count() < 40);
        let heavy = c_of("var a = [3, 1, 2]; a.sort(); var m = { \"k\": 1 }; println(a); println(m);");
        for name in ["arr_sort", "map_put", "user_roots"] {
            assert!(heavy.contains(name), "{name}");
        }
        assert_eq!(heavy.matches("#include").count(), 1);
    }

    #[test]
    fn the_layout_is_declarations_program_main() {
        let c = c_of("fn sq(x: i64) -> i64 { x * x } fn main() { println(sq(7)); }");
        assert!(!c.contains("inline"));
        let decls = c.find("Declarations").unwrap();
        let user_at = c.find("n_start").unwrap();
        let main_at = c.find("int main(").unwrap();
        assert!(c.find("#include \"neon.h\"").unwrap() < decls && decls < user_at && user_at < main_at);
    }

    #[test]
    fn checks_come_from_the_header() {
        let c = c_of(
            "fn main() { let a = input().parse_i64(); let b = input().parse_i64(); println(a * b); println(a << b); }",
        );
        assert!(c.contains("mul_i64(") && c.contains("shl_i64("));
        // the macros and the checked bodies live in neon.h, behind one switch
        assert!(NEON_H.contains("#ifndef NEON_CHECKS") && NEON_H.contains("#ifdef NDEBUG"));
        assert!(NEON_H.contains("if (UNLIKELY(OVF_MUL(a, b, &r))) trap_overflow();"));
        let rec = c_of("fn f(n: i64) -> i64 { if n == 0 { 0 } else { 1 + f(n - 1) } } fn main() { println(f(5)); }");
        assert!(rec.contains("DEPTH_ENTER();") && rec.contains("DEPTH_LEAVE();"));
        assert!(NEON_H.contains("#define DEPTH_ENTER() ((void)0)"));
    }

    #[test]
    fn closures_get_cells_and_a_collector_frame() {
        let c = c_of(
            "fn make() -> fn() -> i64 { var n = 0; || => { n += 1; n } } fn main() { let f = make(); println(f()); println(f()); }",
        );
        assert!(c.contains("cell_new") && c.contains("clo_new") && c.contains("CELL(up[0])->v"));
        assert!(c.contains("FRAME(") && c.contains("FRAME_LEAVE();"));
    }

    #[test]
    fn recursion_is_guarded_and_plain_code_is_not() {
        let c = c_of("fn f(n: i64) -> i64 { if n == 0 { 0 } else { 1 + f(n - 1) } } fn main() { println(f(5)); }");
        assert!(c.contains("DEPTH_ENTER();"));
        let d = c_of("fn main() { let x = 3.0; println(x * x + 1.0); }");
        assert!(!d.contains("DEPTH_ENTER"));
    }

    fn c_unoptimized(src: &str) -> String {
        let opts = Options { opt: crate::ir::OptConfig::none(), ..Options::default() };
        let c = compile_source("t.neon", src, &MemVfs::new(), &opts);
        assert!(!c.diags.has_errors(), "{}", c.render_diagnostics());
        emit_c(c.ir.as_ref().unwrap()).unwrap()
    }

    #[test]
    fn variables_parameters_fields_and_variants_keep_their_names() {
        let c = c_unoptimized(
            "struct Point { x: i64, y: i64 }\n\
             enum Shape { Circle(i64), Dot }\n\
             fn dist(p: Point, scale: i64) -> i64 { (p.x * p.x + p.y * p.y) * scale }\n\
             fn area(s: Shape) -> i64 { match s { Shape::Circle(r) => r * r, Shape::Dot => 0 } }\n\
             fn main() { var total = 0; let pt = Point { x: 3, y: 4 }; for k in 0..3 { total += dist(pt, k); }\n\
             println(total + area(Shape::Circle(2))); }",
        );
        for name in ["n_dist(Obj *p, i64 scale)", "n_area(Obj *s)", "total", "pt", "Point_x", "Point_y", "Shape_Circle"]
        {
            assert!(c.contains(name), "{name} is missing:\n{c}");
        }
        assert!(c.contains("enum { Point_x, Point_y };") && c.contains("AGG(p)->f[Point_y]"), "{c}");
        assert!(c.contains("TAG(s) != Shape_Circle") && c.contains("agg_new(Shape_Circle"), "{c}");
        // where each function comes from
        assert!(c.contains("/* dist (t.neon:3) */") && c.contains("/* area (t.neon:4) */"), "{c}");
        // no register numbers for what has a name
        assert!(!c.contains(" v1") && !c.contains("(v0"), "{c}");
    }

    #[test]
    fn names_that_clash_with_c_are_made_safe() {
        let c = c_unoptimized(
            "fn f(int: i64, Obj: i64, t: i64, len: i64) -> i64 { let main = int + Obj; let x = t; let x = x + len; main + x }\n\
             fn main() { println(f(1, 2, 3, 4)); }",
        );
        // keywords and the runtime's own names get a suffix; harmless names (`len`) stay
        assert!(
            c.contains("i64 int_2") && c.contains("Obj_2") && c.contains("i64 t_2") && c.contains("i64 len"),
            "{c}"
        );
        assert!(c.contains("main_2") || !c.contains("i64 main "), "{c}");
        // unicode names are not C identifiers: they fall back to temporaries
        let u = c_unoptimized("fn main() { let привет = 5; println(привет + 1); }");
        assert!(!u.contains("привет") && u.contains("n_start") || u.contains("n_main"), "{u}");
    }

    #[test]
    fn structs_with_too_many_fields_are_reported() {
        let fields: String = (0..70).map(|i| format!("x{i}: i64, ")).collect();
        let vals: String = (0..70).map(|i| format!("x{i}: {i}, ")).collect();
        let src = format!("struct Big {{ {fields} }} fn main() {{ let b = Big {{ {vals} }}; println(b.x3); }}");
        let c = compile_source(
            "t.neon",
            &src,
            &MemVfs::new(),
            &Options { opt: crate::ir::OptConfig::none(), ..Options::default() },
        );
        assert!(!c.diags.has_errors(), "{}", c.render_diagnostics());
        let err = emit_c(c.ir.as_ref().unwrap()).unwrap_err();
        assert!(err.contains("64 fields"), "{err}");
    }
}
